text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "一组与三组响应分钟中位数排名",
      "business_question": "计算团队为一组和团队的三组的响应分钟中位数，并按中位数升序排列。约束：只看一组与三组；按团队计算；升序排名。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心问题（比较两组的中位数并排名）或支持决策。这是直接实现分析目标的唯一必要步骤。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "response_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "response_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
